  'uad-3.6-2026-08-13-h1.5', uid, property_context, report_field_id,
  18, 'Project Information', location_role,
  jsonb_build_object(
    'label', label, 'phase', 15,
    'source', 'Appendix C-1 v1.3 and Appendix F-1 v1.4'
